/// The vendor that registered a MAC address, if it is one this table knows.
///
/// Takes the full six-byte address and matches on its first three bytes, which
/// is the assigned portion. Returns `None` for an unrecognised assignment, and
/// for a locally administered address — a randomised MAC identifies nobody, and
/// saying otherwise would be worse than saying nothing.
pub fn vendor_of(mac: [u8; 6]) -> Option<&'static str> {
    if mac[0] & 0b0000_0010 != 0 {
        return None;
    }
    let oui = u32::from_be_bytes([0, mac[0], mac[1], mac[2]]);
    VENDORS
        .binary_search_by_key(&oui, |(prefix, _)| *prefix)
        .ok()
        .map(|index| VENDORS[index].1)
}

/// Whether a MAC address was randomised by the device rather than assigned.
///
/// Phones and laptops rotate these for privacy, so an unrecognised vendor on a
/// randomised address is expected and not a finding.
pub fn is_randomised(mac: [u8; 6]) -> bool {
    mac[0] & 0b0000_0010 != 0
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_so_binary_search_is_valid() {
        // A lookup silently returning None on an unsorted table would make the
        // whole module quietly useless, so this is checked rather than assumed.
        assert!(VENDORS.windows(2).all(|pair| pair[0].0 < pair[1].0), "OUI table is not sorted");
    }

    #[test]
    fn known_household_hardware_is_recognised() {
        assert_eq!(vendor_of([0x14, 0x0A, 0xC5, 0x23, 0x51, 0x20]), Some("Amazon"));
        assert_eq!(vendor_of([0x58, 0xB0, 0x3E, 0x70, 0x01, 0x72]), Some("Nintendo"));
        assert_eq!(vendor_of([0x78, 0x28, 0xCA, 0x14, 0x91, 0xAE]), Some("Sonos"));
        assert_eq!(vendor_of([0x54, 0x07, 0x7D, 0x24, 0x4F, 0xF5]), Some("Netgear"));
    }

    #[test]
    fn a_randomised_address_identifies_nobody() {
        // The second-least-significant bit of the first byte marks a locally
        // administered address. Reporting a vendor for one would be a fiction.
        assert!(is_randomised([0x62, 0x94, 0x73, 0xB2, 0x3B, 0x25]));
        assert_eq!(vendor_of([0x62, 0x94, 0x73, 0xB2, 0x3B, 0x25]), None);
    }

    #[test]
    fn an_unassigned_prefix_is_not_guessed() {
        assert_eq!(vendor_of([0x00, 0x00, 0x00, 0x00, 0x00, 0x01]), None);
    }
}
